#!/usr/bin/env python3
"""Fill safety_audit_template.hwpx with JSON data and output final HWPX.

This script:
- Loads /root/audit_overview.json and /root/corrective_actions.json
- Extracts /root/safety_audit_template.hwpx (a zip) into a temp dir
- Replaces {{placeholders}} across all XML-ish files inside
- Converts inspection date occurrences from YYYY-MM-DD to YYYY.MM.DD
- Appends severity note immediately after each risk tier occurrence
- Removes layout cache elements (<hp:linesegarray>/<hp:lineSegArray>) from modified paragraphs
- Repackages to /root/safety_audit_brief_final.hwpx
"""

import json
import re
import shutil
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET

TEMPLATE_PATH = Path("/root/safety_audit_template.hwpx")
AUDIT_OVERVIEW_PATH = Path("/root/audit_overview.json")
CORRECTIVE_ACTIONS_PATH = Path("/root/corrective_actions.json")
OUTPUT_PATH = Path("/root/safety_audit_brief_final.hwpx")

WORK_DIR = Path("/tmp/hwpx_fill_work")
EXTRACT_DIR = WORK_DIR / "extracted"

SEVERITY_NOTE = {
    "High": "즉시조치",
    "Medium": "계획보완",
    "Low": "모니터링",
}

PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def load_inputs():
    overview = json.loads(AUDIT_OVERVIEW_PATH.read_text(encoding="utf-8"))
    actions = json.loads(CORRECTIVE_ACTIONS_PATH.read_text(encoding="utf-8"))

    summary = overview.get("summary") or {}
    immediate_actions = actions.get("immediate_actions") or []

    if len(immediate_actions) != 3:
        raise ValueError(f"Expected 3 immediate_actions, got {len(immediate_actions)}")

    inspection_date_hyphen = str(summary.get("점검일", ""))
    inspection_date_dotted = inspection_date_hyphen.replace("-", ".")

    risk_tier = str(summary.get("위험등급", ""))
    if risk_tier and risk_tier not in SEVERITY_NOTE:
        raise ValueError(
            f"Unknown 위험등급 '{risk_tier}', expected one of {sorted(SEVERITY_NOTE.keys())}"
        )

    mapping = {
        "점검ID": str(summary.get("점검ID", "")),
        "현장명": str(summary.get("현장명", "")),
        "주관점검자": str(summary.get("주관점검자", "")),
        "점검일": inspection_date_dotted,
        "위험등급": risk_tier,
        "총평": str(summary.get("총평", "")),
        "보고대상": str(summary.get("보고대상", "")),
        "조치1": str(immediate_actions[0]),
        "조치2": str(immediate_actions[1]),
        "조치3": str(immediate_actions[2]),
    }

    return mapping, inspection_date_hyphen, inspection_date_dotted, risk_tier


def get_namespaces(xml_path: Path):
    """Collect namespaces declared in the document to preserve prefixes."""
    ns = {}
    for event, elem in ET.iterparse(str(xml_path), events=("start-ns",)):
        prefix, uri = elem
        # ElementTree uses '' for default namespace
        ns[prefix or ""] = uri
    return ns


def localname(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def is_xml_like(path: Path) -> bool:
    if not path.is_file():
        return False
    try:
        data = path.read_bytes()[:200]
    except OSError:
        return False
    # skip leading whitespace
    data = data.lstrip()
    return data.startswith(b"<?xml")


def substitute_placeholders(text: str, mapping: dict) -> str:
    def repl(m):
        key = m.group(1).strip()
        if key in mapping:
            return mapping[key]
        # leave unknown placeholders untouched; we'll detect leftovers later
        return m.group(0)

    return PLACEHOLDER_RE.sub(repl, text)


def append_severity_note(text: str, risk_tier: str) -> str:
    if not risk_tier:
        return text

    note = SEVERITY_NOTE[risk_tier]
    # Add note only if it isn't already present immediately after.
    # Constrain matches to standalone tokens to avoid altering words like "Highly".
    tier_re = re.compile(
        rf"(?<![A-Za-z]){re.escape(risk_tier)}(?![A-Za-z])"
        rf"(?!\s*(?:즉시조치|계획보완|모니터링))"
    )
    return tier_re.sub(risk_tier + " " + note, text)


def remove_layout_cache_from_paragraph(p_elem: ET.Element):
    # Remove child elements like <hp:linesegarray> / <hp:lineSegArray> (case varies)
    to_remove = []
    for child in list(p_elem):
        if localname(child.tag).lower() == "linesegarray":
            to_remove.append(child)
    for child in to_remove:
        p_elem.remove(child)


def modify_paragraph(p_elem: ET.Element, mapping: dict, date_hyphen: str, date_dotted: str, risk_tier: str) -> bool:
    """Modify the paragraph text if needed. Return True if changed."""

    # Collect all <...:t> elements in this paragraph.
    t_elems = [e for e in p_elem.iter() if localname(e.tag) == "t"]
    if not t_elems:
        return False

    original_parts = [(e.text or "") for e in t_elems]
    original_text = "".join(original_parts)

    new_text = original_text
    new_text = substitute_placeholders(new_text, mapping)

    if date_hyphen:
        new_text = new_text.replace(date_hyphen, date_dotted)

    new_text = append_severity_note(new_text, risk_tier)

    if new_text == original_text:
        return False

    # Write back: store everything in the first <t>, clear the rest.
    t_elems[0].text = new_text
    for e in t_elems[1:]:
        e.text = ""

    remove_layout_cache_from_paragraph(p_elem)
    return True


def process_xml_file(xml_path: Path, mapping: dict, date_hyphen: str, date_dotted: str, risk_tier: str):
    namespaces = get_namespaces(xml_path)
    for prefix, uri in namespaces.items():
        ET.register_namespace(prefix, uri)

    tree = ET.parse(str(xml_path))
    root = tree.getroot()

    changed_any = False
    # Modify paragraphs (<...:p> elements) only; remove cache only there.
    for p in root.iter():
        if localname(p.tag) != "p":
            continue
        if modify_paragraph(p, mapping, date_hyphen, date_dotted, risk_tier):
            changed_any = True

    if changed_any:
        tree.write(str(xml_path), encoding="UTF-8", xml_declaration=True)


def extract_template():
    shutil.rmtree(WORK_DIR, ignore_errors=True)
    EXTRACT_DIR.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(TEMPLATE_PATH, "r") as z:
        z.extractall(EXTRACT_DIR)


def repackage_to_output():
    tmp_out = WORK_DIR / "out.hwpx"
    if tmp_out.exists():
        tmp_out.unlink()

    # Ensure deterministic ordering: mimetype first (uncompressed) if present.
    mimetype_path = EXTRACT_DIR / "mimetype"

    with zipfile.ZipFile(tmp_out, "w") as z:
        if mimetype_path.exists():
            z.write(
                str(mimetype_path),
                arcname="mimetype",
                compress_type=zipfile.ZIP_STORED,
            )

        for fp in sorted(EXTRACT_DIR.rglob("*")):
            if not fp.is_file():
                continue
            rel = fp.relative_to(EXTRACT_DIR).as_posix()
            if rel == "mimetype":
                continue
            z.write(str(fp), arcname=rel, compress_type=zipfile.ZIP_DEFLATED)

    shutil.copyfile(tmp_out, OUTPUT_PATH)


def verify_no_placeholders_left():
    leftovers = []
    for fp in sorted(EXTRACT_DIR.rglob("*")):
        if not fp.is_file():
            continue
        try:
            txt = fp.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        if "{{" in txt:
            leftovers.append(fp)

    if leftovers:
        paths = "\n".join(str(p) for p in leftovers[:20])
        raise RuntimeError(f"Unreplaced placeholders remain in {len(leftovers)} files. Examples:\n{paths}")


def main():
    mapping, date_hyphen, date_dotted, risk_tier = load_inputs()
    extract_template()

    xml_like_files = [fp for fp in EXTRACT_DIR.rglob("*") if is_xml_like(fp)]

    for fp in xml_like_files:
        process_xml_file(fp, mapping, date_hyphen, date_dotted, risk_tier)

    verify_no_placeholders_left()
    repackage_to_output()

    if not OUTPUT_PATH.exists() or OUTPUT_PATH.stat().st_size == 0:
        raise RuntimeError("Output file was not created or is empty")


if __name__ == "__main__":
    main()

